      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 6, 'g', 'required',
     'assaisonnement', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'required',
     'assaisonnement', false, 6);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Compter environ 700 g de pommes de terre en robe pour obtenir les 600 g épluchés déclarés. Les éplucher et les couper en rondelles de trois millimètres, ou en petits morceaux irréguliers d''un centimètre — les deux écoles existent, mais l''épaisseur importe : plus épais, elles restent fermes au cœur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Émincer l''oignon en fines demi-lunes. Chauffer l''huile dans une poêle de vingt-quatre centimètres à feu MOYEN-DOUX et y verser pommes de terre et oignon avec la moitié du sel. Ils doivent frémir doucement et non frire : c''est un pochage à l''huile, pas une friture, et une huile trop chaude donne des pommes de terre croustillantes qui ne se lieront pas aux œufs.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Laisser confire quinze à vingt minutes en remuant de temps en temps, jusqu''à ce qu''une rondelle s''écrase entre deux doigts. Les pommes de terre ne doivent pas colorer, ou à peine. Elles s''attendrissent en absorbant une partie de l''huile — c''est ce que la recette recherche, et c''est aussi pourquoi il en faut plus qu''on n''en mangera.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser le contenu de la poêle dans une passoire posée sur un bol et laisser ÉGOUTTER cinq minutes. L''huile récupérée — la moitié environ — se garde et se réutilise ; c''est elle que la recette précédente comptait dans le plat alors qu''elle n''y entre pas. Réserver deux cuillerées pour la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Battre les œufs dans un grand saladier avec le reste du sel et le poivre, juste assez pour les mêler. Y verser les pommes de terre égouttées encore chaudes et mélanger doucement à la spatule, en écrasant un peu les morceaux contre la paroi. Laisser reposer dix minutes : l''amidon et l''œuf se lient, et c''est ce repos qui donne à la tortilla sa tenue à la découpe.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Chauffer deux cuillerées de l''huile réservée dans la poêle à feu moyen, y verser l''appareil, l''égaliser et rabattre les bords vers le centre à la spatule pendant la première minute. Baisser à feu doux et laisser prendre six à huit minutes : le dessous doit être doré et le dessus encore liquide.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Poser une grande assiette plate sur la poêle, la plaquer d''une main et RETOURNER l''ensemble d''un geste franc et rapide, au-dessus de l''évier. L''hésitation est ce qui rate ce geste, pas la maladresse. Refaire glisser la tortilla dans la poêle côté cru dessous et cuire cinq à six minutes de plus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'La tortilla est prête quand elle est ferme sur les bords et souple au centre sous le doigt : les Espagnols la préfèrent « jugosa », c''est-à-dire encore un peu coulante à cœur. La faire glisser sur un plat et attendre au moins dix minutes avant de couper — chaude, elle s''effondre ; tiède, elle se tranche net et se mange aussi bien froide le lendemain.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
