DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Taboulé libanais', 'taboule libanais', 'Liban', 'Liban',
     'meal', 'taboulé, salade d''herbes crues', 'named_traditional_dish', 'fresh_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Taboulé libanais', 'Salade dense de persil plat haché, tomates, oignon nouveau et boulgour, assaisonnée au citron', ds.id, 'REAL-138',
    'Myko', 'editorial', 6, 35, 0, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '21e4278a6a2b59f3094a75474844367d',
    '{"sweet":1,"salty":3,"acidic":5,"bitter":1,"umami":1,"heat":0,"pungency":2,"richness":2,"freshness":5,"intensity":3}'::jsonb, ARRAY['persil','citron','menthe','huile d''olive']::text[],
    ARRAY['herbes fraîches coupées','agrume','menthe','oignon cru']::text[], ARRAY['hachis fin et aéré','grain de boulgour tendre','dés de tomate fermes']::text[],
    ARRAY['Persil plat frais','Boulgour fin cru','Jus de citron frais','Menthe fraîche']::text[], ARRAY['Le persil est l''ingrédient principal et non l''herbe d''appoint : 250 g de feuilles contre 45 g de boulgour, cinq fois et demie plus','Le boulgour reste minoritaire et jamais cuit, gonflé à l''eau froide — remplacé en volume par de la semoule de couscous, on obtient le taboulé français, qui est un autre plat','Citron abondant, huile mesurée : sans acidité franche, un hachis d''herbes crues n''a plus de colonne','Hachage au couteau seulement : le persil passé au robot noircit et rend son eau, et la texture du plat est perdue','Rien de cuit, rien de tiède dans le saladier']::text[],
    ARRAY['trempage à froid du boulgour','hachage au couteau','épépinage des tomates','frottage de l''oignon au sel','assaisonnement en deux temps']::text[], ARRAY['Au quinoa plutôt qu''au boulgour : 80 g pour trois, cuits à l''eau puis refroidis (chefsimon)','Au persil frisé plutôt que plat, deux petits bouquets pour quatre (chefsimon, deux versions)','Version plus chargée en blé : 200 g de boulgour fin pour huit, avec de l''oignon jaune à la place de l''oignon nouveau (chefsimon)','Une cuillerée à soupe de menthe séchée en plus de la menthe fraîche (chefsimon)','Une pincée de piment d''Espelette et une pointe de cannelle, toutes deux données pour facultatives (750g)','Un demi-concombre en petits dés ajouté au moment du service (chefsimon)']::text[], ARRAY['gluten']::text[],
    'Se garde 2 jours au réfrigérateur, couvert, mais perd sa tenue dès le premier : le persil fane et la tomate rend son eau. Ne se congèle pas, les herbes crues ressortant noires et détrempées. Pour préparer d''avance, hacher et réserver les éléments séparément au froid et n''assembler avec le citron et l''huile qu''un quart d''heure avant de servir. Égoutter le fond du saladier et rectifier le citron avant de resservir un reste.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
