  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-144', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('2fcb8c4ea9e47e470ca1950167517b12'::text), 'myko_v3_canonical_recipe'),
