         'v3:REAL-177', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('43d492ef6e645697527fe6630b016ec2'::text), 'myko_v3_canonical_recipe'),
